//! Bit-exact port of `hg::random_number_generator`
//! (`include/SSVOpenHexagon/Core/RandomNumberGenerator.{hpp,cpp}`), backed by
//! `ssvu::pcg32_fast` (see [`pcg`]).
//!
//! The `get_int` / `get_real` methods reproduce **libstdc++ 15.2**
//! `std::uniform_int_distribution` / `std::uniform_real_distribution` sampling
//! (read from the installed `/usr/include/c++/15/bits/{uniform_int_dist.h,
//! random.h, random.tcc}`) so that replay RNG streams match the C++ build.
//!
//! Ground truth: `.agents/plans/001-rust-port/mapping/oracle-vectors.md`
//! (generated by compiling the C++ sources at commit `1e2cba71` with
//! `g++ -std=c++20` on this machine).

pub mod pcg;

pub use pcg::Pcg32Fast;

/// `random_number_generator_seed_type` == `unsigned long long`
/// (`include/SSVOpenHexagon/Core/RandomNumberGeneratorTypes.hpp`).
pub type Seed = u64;

/// `random_number_generator::state_type` == `engine_type::state_type` == `u64`.
pub type State = u64;

/// Port of `hg::random_number_generator`.
///
/// C++ structure mirrored:
/// ```cpp
/// explicit random_number_generator(const seed_type seed) noexcept;
///     // : _seed{seed}, _rng{seed} { advance(1); }   // RandomNumberGenerator.cpp
/// [[nodiscard]] seed_type seed() const noexcept;
/// template <typename T> T get_int(T min, T max) noexcept;
/// template <typename T> T get_real(T min, T max) noexcept;
/// void advance(const state_type delta) noexcept;
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RandomNumberGenerator {
    seed: Seed,
    engine: Pcg32Fast,
}

impl RandomNumberGenerator {
    /// C++ ctor: constructs the engine from the seed, then calls
    /// `advance(1)` (see `RandomNumberGenerator.cpp`).
    pub fn new(seed: Seed) -> Self {
        let mut engine = Pcg32Fast::from_seed(seed);
        engine.advance(1);
        Self { seed, engine }
    }

    /// C++ `seed()` accessor (returns the stored seed, not the state).
    #[must_use]
    pub fn seed(&self) -> Seed {
        self.seed
    }

    /// Port of `get_int<T>(min, max)` for the integral types the game uses
    /// (`int` via the Lua API; unsigned variants for parity with the C++
    /// template). Delegates to [`uniform_int`].
    #[must_use]
    pub fn get_int<T: IntDist>(&mut self, min: T, max: T) -> T {
        debug_assert!(min <= max, "SSVOH_ASSERT(min <= max)");
        uniform_int(&mut self.engine, min, max)
    }

    /// Port of `get_real<T>(min, max)` for `float` / `double`.
    /// Delegates to [`uniform_real`].
    #[must_use]
    pub fn get_real<T: RealDist>(&mut self, min: T, max: T) -> T {
        debug_assert!(min <= max, "SSVOH_ASSERT(min <= max)");
        uniform_real(&mut self.engine, min, max)
    }

    /// C++ `advance(const state_type delta)` — `_rng.advance(delta)`.
    pub fn advance(&mut self, delta: State) {
        self.engine.advance(delta);
    }
}

// ---------------------------------------------------------------------------
// std::uniform_int_distribution (libstdc++ 15.2, bits/uniform_int_dist.h)
// ---------------------------------------------------------------------------

/// Integral types accepted by [`uniform_int`] / `get_int`.
///
/// Mirrors the C++ `get_int<T>` template; the game uses `int` (Lua API),
/// unsigned variants are provided for parity.
pub trait IntDist: PartialOrd + Sized {
    /// libstdc++ `uniform_int_distribution<T>::operator()` for our u32 engine.
    fn draw(rng: &mut Pcg32Fast, min: Self, max: Self) -> Self;
}

macro_rules! impl_int_dist {
    ($t:ty) => {
        impl IntDist for $t {
            /// ```cpp
            /// __urngrange = u32::MAX - 0;                  // == __UINT32_MAX__
            /// __urange    = u32(b) - u32(a);               // in __uctype
            /// if (__urngrange == __urange) return a + raw(); // full width
            /// // else downscale via Lemire _S_nd<u64>(urng, u32erange = __urange + 1)
            /// return a + u32(__product >> 32);            // `__ret + a`
            /// ```
            fn draw(rng: &mut Pcg32Fast, min: $t, max: $t) -> $t {
                // __uctype(__param.b()) - __uctype(__param.a())  (modular, C++20)
                let urange: u32 = (max as u32).wrapping_sub(min as u32);
                let value: u32 = if urange == u32::MAX {
                    // __urngrange == __urange: the range spans the whole
                    // engine width; libstdc++ takes the raw engine value.
                    rng.next_u32()
                } else {
                    let n = urange.wrapping_add(1); // __uerange, in 1..=u32::MAX
                    lemire_u32(rng, n)
                };
                // C++: `return __ret + __param.a();` (unsigned add, then convert)
                (min as u32).wrapping_add(value) as $t
            }
        }
    };
}

impl_int_dist!(i32);
impl_int_dist!(u32);

/// The distribution itself (engine-agnostic entry point, mirroring the
/// `std::uniform_int_distribution<T>` call sites in the C++ wrapper).
pub fn uniform_int<T: IntDist>(rng: &mut Pcg32Fast, min: T, max: T) -> T {
    T::draw(rng, min, max)
}

/// `_S_nd<__UINT64_TYPE__>(__urng, __u32erange)` from `uniform_int_dist.h`:
/// Lemire's nearly divisionless bounded draw on a full-width `u32` engine.
fn lemire_u32(rng: &mut Pcg32Fast, n: u32) -> u32 {
    // `-__range % __range` in u32 == (2^32 - n) % n == 2^32 % n (0 if n | 2^32)
    let threshold = 0u32.wrapping_sub(n) % n;
    loop {
        let product = u64::from(rng.next_u32()) * u64::from(n);
        let low = product as u32;
        if !(low < threshold) {
            return (product >> 32) as u32;
        }
    }
}

// ---------------------------------------------------------------------------
// std::uniform_real_distribution (libstdc++ 15.2, bits/random.h + random.tcc)
// ---------------------------------------------------------------------------

/// Real types accepted by [`uniform_real`] / `get_real`.
///
/// Mirrors the C++ `get_real<T>` template; the game uses `float` (Lua API,
/// HGUpdate camera shake) and `double` (parity with the C++ template).
pub trait RealDist: Sized + PartialOrd {
    /// `std::generate_canonical<T, T::digits>` from the engine (u32).
    fn canonical(rng: &mut Pcg32Fast) -> Self;
}

impl RealDist for f32 {
    /// `generate_canonical<float, 24>` (`bits/random.tcc`):
    /// `__b = 24`, `__r = 2^32 + 1` (exact in `long double`),
    /// `__log2r = log2(2^32 + 1)` truncates to `32`,
    /// `__m = max(1, (24 + 32 - 1) / 32) = 1` draw.
    ///
    /// `__tmp *= __r` converts `4294967297.0L` to `f32`, which is exactly
    /// `2^32`, so this is `f32(x) / 2^32` in the C++ order of operations.
    fn canonical(rng: &mut Pcg32Fast) -> f32 {
        let r: f32 = 4294967297.0; // f32(4294967297.0L) == 4294967296.0f == 2^32
        let mut sum = 0.0f32;
        let mut tmp = 1.0f32;
        // for (__k = __m; __k != 0; --__k) — one iteration:
        sum += f32::from(rng.next_u32()) * tmp;
        tmp *= r;
        let mut ret = sum / tmp;
        if ret >= 1.0f32 {
            ret = f32::next_after(1.0f32, 0.0f32);
        }
        ret
    }
}

impl RealDist for f64 {
    /// `generate_canonical<double, 53>` (`bits/random.tcc`):
    /// `__b = 53`, `__log2r = 32` (truncated),
    /// `__m = max(1, (53 + 32 - 1) / 32) = 2` draws.
    /// `__r` is exact in `f64` (`2^32 + 1 < 2^53`).
    fn canonical(rng: &mut Pcg32Fast) -> f64 {
        let r: f64 = 4294967297.0;
        let mut sum = 0.0f64;
        let mut tmp = 1.0f64;
        // for (__k = __m; __k != 0; --__k) — k = 2 (first engine draw):
        sum += f64::from(rng.next_u32()) * tmp;
        tmp *= r;
        // k = 1 (second engine draw):
        sum += f64::from(rng.next_u32()) * tmp;
        tmp *= r;
        let mut ret = sum / tmp;
        if ret >= 1.0f64 {
            ret = f64::next_after(1.0f64, 0.0f64);
        }
        ret
    }
}

/// libstdc++ 15.2 `std::uniform_real_distribution<T>::operator()`:
///
/// ```cpp
/// __detail::_Adaptor<urng, T> __aurng(__urng);
/// return (__aurng() * (__p.b() - __p.a())) + __p.a();
/// ```
///
/// where `_Adaptor::operator()()` is `std::generate_canonical<T, T::digits>`.
pub fn uniform_real<T: RealDist>(rng: &mut Pcg32Fast, min: T, max: T) -> T {
    let x = T::canonical(rng);
    // `(__aurng() * (__p.b() - __p.a())) + __p.a()` — same order of operations.
    x * (max - min) + min
}

// ---------------------------------------------------------------------------
// Oracle tests — every value in
// .agents/plans/001-rust-port/mapping/oracle-vectors.md
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    /// Pins the raw `pcg32_fast` stream for seed 12345 (oracle "raw=..." block).
    #[test]
    fn oracle_raw_stream_seed_12345() {
        let mut rng = Pcg32Fast::from_seed(12345);
        let expected = [
            0u32, 360236480, 3576984158, 3399133164, 3953016716, 1075407150,
            134550159, 1121230050,
        ];
        for &e in &expected {
            assert_eq!(rng.next_u32(), e, "raw engine stream mismatch (seed 12345)");
        }
    }

    /// Pins the engine `min()` / `max()` (oracle "# engine min/max").
    #[test]
    fn oracle_engine_min_max() {
        assert_eq!(Pcg32Fast::min(), 0);
        assert_eq!(Pcg32Fast::max(), 4294967295);
    }

    /// Pins `std::uniform_int_distribution<int>{0,5}` over a fresh
    /// `pcg32_fast{12345u}` (oracle "int=..." block). Non-power-of-two range
    /// exercises the Lemire threshold/rejection path.
    #[test]
    fn oracle_uniform_int_0_5_seed_12345() {
        let mut rng = Pcg32Fast::from_seed(12345);
        let expected = [0i32, 4, 4, 5, 1, 0, 1, 0];
        for &e in &expected {
            assert_eq!(
                uniform_int::<i32>(&mut rng, 0, 5),
                e,
                "uniform_int_distribution<int>{{0,5}} stream mismatch (seed 12345)"
            );
        }
    }

    /// Pins the unsigned-variant path (`uniform_int_distribution<unsigned>`
    /// shares the `u32` uctype with `int`) on a fresh engine.
    #[test]
    fn uniform_int_u32_same_stream_as_i32() {
        let mut rng = Pcg32Fast::from_seed(12345);
        let expected = [0u32, 4, 4, 5, 1, 0, 1, 0];
        for &e in &expected {
            assert_eq!(uniform_int::<u32>(&mut rng, 0, 5), e);
        }
    }

    /// Pins the non-power-of-two range `{0,2}` (issue 01 risk note: pin
    /// non-power-of-two ranges beyond `{0,5}`). Values generated by the C++
    /// probe (`std::uniform_int_distribution<int>{0,2}` on
    /// `pcg32_fast{12345u}`, g++ 15.2, `-O0`).
    #[test]
    fn uniform_int_0_2_seed_12345() {
        let mut rng = Pcg32Fast::from_seed(12345);
        let expected = [0i32, 2, 2, 2, 0, 0, 0, 0, 1, 1, 0, 2];
        for &e in &expected {
            assert_eq!(
                uniform_int::<i32>(&mut rng, 0, 2),
                e,
                "uniform_int_distribution<int>{{0,2}} stream mismatch (seed 12345)"
            );
        }
    }

    /// Pins `std::uniform_real_distribution<float>{0.f,1.f}` over a fresh
    /// `pcg32_fast{12345u}` (oracle "real=..." block), bit-exactly. The
    /// decimal values match the oracle (`%.9g`); the bit patterns were
    /// regenerated by the C++ probe (g++ 15.2, same engine + distribution).
    #[test]
    fn oracle_uniform_real_f32_0_1_seed_12345() {
        let mut rng = Pcg32Fast::from_seed(12345);
        // 0, 0.0838740915, 0.832831502, 0.791422367, 0.920383453,
        // 0.250387728, 0.0313274004, 0.261056721  (oracle, %.9g)
        let expected_bits = [
            0x00000000u32, // 0
            0x3DABC62E, // 0.0838740915
            0x3F553472, // 0.832831502
            0x3F4A9AA8, // 0.791422367
            0x3F6B9E40, // 0.920383453
            0x3E8032D2, // 0.250387728
            0x3D005129, // 0.0313274004
            0x3E85A93A, // 0.261056721
        ];
        for &bits in &expected_bits {
            let got = uniform_real::<f32>(&mut rng, 0.0, 1.0);
            assert_eq!(
                got.to_bits(),
                bits,
                "uniform_real_distribution<float>{{0,1}} stream mismatch (seed 12345)"
            );
        }
    }

    /// Pins `std::uniform_real_distribution<double>{0.0,1.0}` over a fresh
    /// `pcg32_fast{12345u}`, bit-exactly. The double path consumes two engine
    /// draws per value (`__m = 2` in `generate_canonical`). Values generated
    /// by the C++ probe (g++ 15.2, `%.17g` + bit pattern).
    #[test]
    fn uniform_real_f64_0_1_seed_12345() {
        let mut rng = Pcg32Fast::from_seed(12345);
        // 0.083874091506004333, 0.79142236263324306, 0.250387739138767,
        // 0.26105671423285443 (C++ probe)
        let expected_bits = [
            0x3FB578C5C0000000u64, 0x3FE95354FD9AA68E, 0x3FD0065A4BBAE790,
            0x3FD0B52738820145,
        ];
        for &bits in &expected_bits {
            let got = uniform_real::<f64>(&mut rng, 0.0, 1.0);
            assert_eq!(
                got.to_bits(),
                bits,
                "uniform_real_distribution<double>{{0,1}} stream mismatch (seed 12345)"
            );
        }
    }

    /// Pins `advance(100)` jump-ahead on a fresh `pcg32_fast{12345u}`
    /// (oracle "adv100=1060274396").
    #[test]
    fn oracle_advance_100_seed_12345() {
        let mut rng = Pcg32Fast::from_seed(12345);
        rng.advance(100);
        assert_eq!(rng.next_u32(), 1060274396);
    }

    /// Pins the first output for edge seeds 0 and 4294967295
    /// (oracle "seed0=0", "seedmax=1023").
    #[test]
    fn oracle_edge_seeds_0_and_4294967295() {
        let mut rng0 = Pcg32Fast::from_seed(0);
        assert_eq!(rng0.next_u32(), 0);
        let mut rng_max = Pcg32Fast::from_seed(4294967295);
        assert_eq!(rng_max.next_u32(), 1023);
    }

    /// Pins the `hg::random_number_generator` ctor behavior: engine seeded
    /// from the seed, then `advance(1)` — so the first draw is the second raw
    /// value of the engine stream, and `seed()` returns the stored seed.
    ///
    /// The `[0, 4, 4, 5]` int stream is the C++ probe's
    /// `hgint05` (engine advanced by 1, `uniform_int_distribution<int>{0,5}`).
    #[test]
    fn rng_ctor_seeds_engine_and_advances_one() {
        let mut g = RandomNumberGenerator::new(12345);
        assert_eq!(g.seed(), 12345);
        // raw stream (seed 12345): [0, 360236480, 3576984158, ...]
        // full-width int range returns the raw engine value (post-advance).
        assert_eq!(g.get_int(0u32, u32::MAX), 360236480);
        assert_eq!(g.get_int(0u32, u32::MAX), 3576984158);
        let expected_int05 = [0i32, 4, 4, 5];
        for &e in &expected_int05 {
            assert_eq!(g.get_int(0, 5), e, "hg wrapper int{0,5} stream mismatch");
        }
    }

    /// Pins `RandomNumberGenerator::advance` delegating to the engine.
    #[test]
    fn rng_advance_matches_engine_jump_ahead() {
        let mut g = RandomNumberGenerator::new(12345);
        g.advance(100);
        // engine state after ctor's advance(1) plus advance(100) == advance(101)
        let mut direct = Pcg32Fast::from_seed(12345);
        direct.advance(101);
        assert_eq!(g.get_int(0u32, u32::MAX), direct.next_u32());
    }

    /// Pins the full-width i32 range (min..=max spans the whole u32 width):
    /// libstdc++ takes the raw engine value (no Lemire scaling), offset by
    /// `a` in the C++ unsigned-add order.
    ///
    /// Values from the C++ probe (`intfull`, `pcg32_fast{12345u}`).
    #[test]
    fn uniform_int_i32_full_width_returns_raw_value() {
        let mut rng = Pcg32Fast::from_seed(12345);
        let expected = [
            -2147483648i32, // raw[0] = 0 -> 0 + 2^31 (mod 2^32)
            -1787247168, // raw[1] = 360236480
            1429500510, // raw[2] = 3576984158
            1251649516, // raw[3] = 3399133164
        ];
        for &e in &expected {
            assert_eq!(
                uniform_int::<i32>(&mut rng, i32::MIN, i32::MAX),
                e,
                "full-width int range mismatch (seed 12345)"
            );
        }
    }
}
